    total = total + (int) squares_stride1((int[]){ 1, 2, 3, 100, 200 }, 5);
    total = total + (int) (product_bucket1(323456LL, 4001LL) % 1000);
    total = total + (int) (mix_origin1(4ULL, 3) % 997);
