    total = total + (int) ratio_window1(8, 2);
    total = total + convert_column1(4);
    total = total + (int) squares_credit1((int[]){ 0, 1, 2, 100, 200 }, 5);
    total = total + (int) (product_ledger1(223456LL, 3001LL) % 1000);
    total = total + (int) (mix_sample1(3ULL, 3) % 997);
    total = total + (int) (blend_signal1(5, 2.0f, 4) * 2.0f);
    total = total + (int) ratio_target1(7, 1);
    total = total + convert_anchor2(3);
    total = total + (int) squares_buffer2((int[]){ 6, 7, 8, 100, 200 }, 5);
    total = total + (int) (product_cursor2(123456LL, 2001LL) % 1000);
    total = total + (int) (mix_header2(2ULL, 3) % 997);
    total = total + (int) (blend_margin2(4, 2.0f, 3) * 2.0f);
    total = total + (int) ratio_marker2(6, 8);
